const section = (title, html, learning, written) => ({ title, html, learning, written });

const COURSE_MODULES = [
  {
    id: 1,
    title: 'Systems that sense and respond',
    subtitle: 'Read any control system as input, processing and output.',
    activity: 'Control-system detective',
    sections: [
      section('1.1 Input → process → output', `<p>A control system receives information through an <strong>input</strong>, makes a decision during <strong>processing</strong>, then causes an <strong>output</strong>. A torch button, automatic door and school bell use different components, but the same input–process–output pattern helps explain each system.</p><p>For an alarm, a sensor supplies data, the program compares that data with a rule, and LEDs or a buzzer communicate the response. The three stages are connected: changing the input or processing rule can change the output.</p>`, {term:'input–process–output model',definition:'a model that traces information entering a system, being processed and causing an output',purpose:'explain how the parts of a control system work together',action:'name the real input, the decision made by the code and the resulting output',badAction:'list components without explaining the information flow',benefit:'a complex system can be broken into parts that are easier to design and test',risk:'calling every component an input hides what the program actually controls',control:'follow one signal from its source through the program to the response',evidence:'a labelled IPO diagram plus a sentence explaining the signal path',misconception:'processing means the computer is simply switched on',correction:'processing is the rule or calculation applied to input data',scenario:'An LDR reading falls below a threshold and an LED turns on.',response:'identify the LDR as input, the comparison as processing and the LED as output'}, {prompt:'Explain one everyday control system using input, processing and output.',clarify:'Choose a real system, name the three stages and show how information moves between them.',starter:'The system receives… The program or mechanism then… As a result…',example:'An automatic night light receives an LDR reading as input. Its program compares the reading with a threshold. When the reading is low enough, the lamp turns on as the output.'}),
      section('1.2 Microcontrollers make decisions', `<p>A <strong>microcontroller</strong> is a small programmable computer designed to control a system. The Arduino runs one uploaded sketch repeatedly and uses its pins to communicate with connected inputs and outputs.</p><p>The ThinkerShield places classroom components around the Arduino so the focus can stay on code and systems thinking. The board does not invent the behaviour: the student’s algorithm and code tell the microcontroller what data to read and what action to take.</p>`, {term:'microcontroller',definition:'a programmable device that reads inputs, runs instructions and controls outputs',purpose:'provide the processing stage in an electronic control system',action:'upload a tested sketch that configures pins and applies clear rules',badAction:'assume the board will decide what to do without a program',benefit:'one compact device can coordinate several inputs and outputs',risk:'a wrong pin mode or rule can make correct hardware appear faulty',control:'check the sketch structure, pin numbers and expected signal path',evidence:'a hardware explanation that connects the Arduino, shield, sketch and components',misconception:'the ThinkerShield is the program',correction:'the shield provides components while the uploaded sketch provides behaviour',scenario:'The correct LED is connected but never responds after upload.',response:'check the programmed pin, pinMode and decision rule before blaming the component'}, {prompt:'Explain the different jobs of the Arduino, ThinkerShield and uploaded sketch.',clarify:'Describe the processor, the attached component platform and the instructions without treating them as the same thing.',starter:'The Arduino… The ThinkerShield… The uploaded sketch…',example:'The Arduino is the microcontroller that runs instructions. The ThinkerShield provides accessible inputs and outputs. The sketch sets the rules that connect those components into a working system.'}),
      section('1.3 Work within the real system', `<p>This course uses fixed ThinkerShield connections: push button on digital pin 7, LDR on analogue input A4, potentiometer on analogue input A5, six LEDs on pins 8–13 and the buzzer on pin 3. Pin numbers in code must match the actual board.</p><p>Handle the equipment only as directed, connect the blue USB cable carefully and keep the board on a clear, stable workspace. Lesson access, damaged equipment procedures and any additional classroom controls remain <strong>Teacher to confirm</strong>.</p>`, {term:'system constraint',definition:'a real limit or fixed condition that a design must work within',purpose:'keep code, hardware and project decisions compatible with the available system',action:'use the authorised pin map and teacher-directed equipment routines',badAction:'change pin numbers randomly when the board does not respond',benefit:'testing becomes repeatable because the hardware and code refer to the same connections',risk:'forcing connectors or using the wrong pin can damage equipment or create misleading faults',control:'stop, compare the sketch with the supplied pin map and ask when unsure',evidence:'an accurate annotated pin map used in the project plan',misconception:'a constraint prevents creative design',correction:'constraints define the real space in which a workable creative solution is developed',scenario:'A sketch sends the buzzer command to pin 11.',response:'change the sketch to the authorised buzzer pin 3 and retest under teacher direction'}, {prompt:'Create a hardware map for the final alarm and explain why fixed pin numbers matter.',clarify:'List every authorised input and output, then connect correct pin information to reliable testing.',starter:'The available inputs are… The outputs are… Fixed pins matter because…',example:'The button uses pin 7, the LDR A4 and the potentiometer A5. The LEDs use pins 8–13 and the buzzer pin 3. Matching code to this map lets each command reach the intended component.'})
    ]
  },
  {
    id: 2, title: 'Make light obey the code', subtitle: 'Build reliable digital outputs with setup, loop and timing.', activity: 'Getting Flashy laboratory',
    sections: [
      section('2.1 A sketch has a working structure', `<p>An Arduino sketch normally contains <code>setup()</code> and <code>loop()</code>. Setup runs once after the board starts or resets. It is used to prepare the system, including setting an LED pin as an output. Loop then repeats the behaviour inside it.</p><pre><code>void setup() { pinMode(8, OUTPUT); }
void loop()  { digitalWrite(8, HIGH); }</code></pre><p>Braces group the instructions that belong to each function. Semicolons finish most commands.</p>`, {term:'Arduino sketch structure',definition:'the organised setup and repeating loop that contain a program’s instructions',purpose:'separate one-time configuration from behaviour that must repeat',action:'configure the pin in setup and place repeated output behaviour in loop',badAction:'remove braces or scatter commands outside functions',benefit:'the program is easier to trace, compile and change',risk:'a missing brace or semicolon can stop verification before upload',control:'format the sketch and check the line before the reported error',evidence:'an annotated sketch identifying setup, loop, braces and commands',misconception:'setup repeats continuously',correction:'setup runs once while loop repeats until the board stops or resets',scenario:'An LED must flash continuously after the board starts.',response:'configure its pin in setup and place the on/off sequence in loop'}, {prompt:'Annotate a short Blink sketch to explain setup, loop, braces and semicolons.',clarify:'Explain what each structural part does, not merely where it appears.',starter:'Setup is used to… Loop is used to… The braces… Semicolons…',example:'Setup runs once and declares the LED pin as an output. Loop repeats the on and off commands. Braces group each function, while semicolons finish individual instructions.'}),
      section('2.2 Digital outputs have two states', `<p><code>digitalWrite(pin, HIGH)</code> sends the on state to a configured digital output; <code>LOW</code> sends the off state. On the ThinkerShield, the LED pin must match the LED being controlled.</p><p>Changing a pin number changes the destination, not the meaning of HIGH or LOW. Predict the target and state before uploading so the result can be checked against an expectation.</p>`, {term:'digital output',definition:'an output controlled using two discrete states such as HIGH and LOW',purpose:'switch a component predictably under program control',action:'set the correct pin as OUTPUT and write HIGH or LOW to that pin',badAction:'send output commands to an unrelated or unconfigured pin',benefit:'the program can create clear, testable on and off behaviour',risk:'wrong pin numbers make the observed output differ from the intended one',control:'trace the number through pinMode and digitalWrite before upload',evidence:'a prediction table that matches commands to LED states',misconception:'HIGH means a physically higher LED',correction:'HIGH is a logic state sent by the microcontroller',scenario:'The sketch writes HIGH to pin 10 and LOW to pin 11.',response:'predict that the LED on pin 10 is on while the LED on pin 11 is off'}, {prompt:'Predict and explain the result of a two-LED digitalWrite sequence.',clarify:'Name the pin, state and visible result for each command in order.',starter:'When the code writes… to pin…, the LED… Next…',example:'Writing HIGH to pin 10 turns that output on. Writing LOW to pin 11 turns that output off, provided both pins were configured as outputs.'}),
      section('2.3 Timing makes a sequence visible', `<p><code>delay(milliseconds)</code> pauses the program for a set time. One thousand milliseconds equals one second. A basic flash needs an on command, a delay, an off command and another delay.</p><p>Shorter delays usually make the cycle repeat faster; longer delays make it slower. Delay pauses the whole sketch, so later modules also consider how timing choices affect a combined system.</p>`, {term:'program timing',definition:'the controlled duration and order of actions in a program',purpose:'make output changes happen at a useful and observable pace',action:'place deliberate delays between changed output states',badAction:'change several timing values without predicting the effect',benefit:'light patterns can communicate warnings, states or rhythms',risk:'very long delays can make the system appear frozen and unable to respond',control:'change one timing value, predict the new cycle and measure the result',evidence:'a test record comparing delay values with observed flash behaviour',misconception:'a smaller delay makes the flash slower',correction:'shorter pauses normally let the on/off cycle repeat faster',scenario:'Both 1000 millisecond delays are changed to 200 milliseconds.',response:'expect the LED to flash more quickly and confirm by observing repeated cycles'}, {prompt:'Design a recognisable two-LED signal and justify its timing values.',clarify:'Write the command order and explain how the timing communicates the intended message.',starter:'The pattern begins with… It waits… I chose this timing because…',example:'The first LED turns on for 200 ms, turns off, then the second LED turns on for 600 ms. The unequal timing makes the warning pattern easier to recognise than a steady light.'})
    ]
  },
  {
    id: 3, title: 'Plan the logic before coding', subtitle: 'Turn ideas into precise algorithms, pseudocode and flowcharts.', activity: 'Algorithm and flowchart studio',
    sections: [
      section('3.1 Algorithms are ordered solutions', `<p>An <strong>algorithm</strong> is a finite sequence of unambiguous steps used to solve a problem. For a flashing LED, the order matters: configure the output, turn it on, wait, turn it off, wait and repeat.</p><p>A useful algorithm is precise enough for another person to follow and test. “Make it flash nicely” is an intention, not an algorithm.</p>`, {term:'algorithm',definition:'a finite sequence of clear ordered steps that solves a problem',purpose:'plan and communicate a solution before translating it into code',action:'write each operation in the order it must occur',badAction:'use vague instructions that require the reader to guess',benefit:'logic faults can be found before syntax is involved',risk:'missing or reordered steps can produce the wrong system behaviour',control:'dry-run the steps with a simple example and expected result',evidence:'numbered instructions that another student can trace without guessing',misconception:'an algorithm must be written in Arduino syntax',correction:'an algorithm describes the logic and can be represented in several forms',scenario:'A plan says “turn the LED on, then repeat” but never turns it off.',response:'add the missing wait, off and second wait steps before the repeat'}, {prompt:'Write and dry-run an algorithm for a repeating two-light pattern.',clarify:'Give clear ordered steps, then trace one complete cycle to prove the order works.',starter:'START… Set… Turn… Wait… Repeat… During one cycle…',example:'START; prepare both LED outputs; turn LED 1 on; wait; turn LED 1 off and LED 2 on; wait; turn LED 2 off; repeat. One dry-run ends with both lights off before restarting.'}),
      section('3.2 Pseudocode keeps attention on logic', `<p><strong>Pseudocode</strong> uses structured plain language to express an algorithm without demanding exact programming syntax. Words such as START, READ, IF, ELSE, SET and REPEAT make the control flow visible.</p><p>Indentation shows which steps belong inside a branch or loop. Consistent names, such as <code>lightReading</code>, reduce confusion when the plan becomes code.</p>`, {term:'pseudocode',definition:'structured plain-language instructions that express program logic without exact code syntax',purpose:'make an algorithm readable and ready to translate into code',action:'use consistent action words, names and indentation',badAction:'mix vague sentences with unexplained code fragments',benefit:'the programmer can focus on decisions and sequence before syntax',risk:'poor indentation can hide which actions belong to a condition',control:'read each line aloud and trace the path for different inputs',evidence:'pseudocode with named inputs, decisions and outputs',misconception:'pseudocode has one compulsory programming grammar',correction:'it should be consistent and unambiguous, but it is not a specific programming language',scenario:'An ELSE action is aligned as though it happens every time.',response:'indent it under ELSE so the alternative path is clear'}, {prompt:'Write pseudocode for an alarm that has a normal state and an alert state.',clarify:'Include the input read, condition, both branches and the outputs in each branch.',starter:'START… READ… IF… THEN… ELSE… REPEAT…',example:'READ lightReading. IF lightReading is below the threshold THEN turn the red LED and buzzer on. ELSE turn the green LED on and buzzer off. REPEAT.'}),
      section('3.3 Flowcharts show paths and decisions', `<p>A flowchart uses agreed shapes: an oval for start or end, a rectangle for a process, a parallelogram for input or output, and a diamond for a decision. Arrows show the direction of control.</p><p>A decision must be a question or condition with labelled paths such as Yes/No or True/False. In the new syllabus, <strong>branching</strong> means selecting different actions depending on a condition.</p>`, {term:'conditional branching',definition:'selecting different actions depending on whether a condition is true or false',purpose:'allow a program to respond differently to different input states',action:'place the condition in a decision diamond and label both outgoing paths',badAction:'draw one unlabelled path from a decision',benefit:'alternative behaviours can be traced and tested separately',risk:'a missing branch can leave the system with no defined response',control:'test the flowchart once with the condition true and once false',evidence:'a flowchart with correct symbols, arrows and labelled branches',misconception:'branching means saving a backup copy of code',correction:'in this syllabus, branching is conditional control flow',scenario:'The question “Is the button pressed?” appears in a process rectangle.',response:'move the condition to a decision diamond and label both paths'}, {prompt:'Draw or describe a complete flowchart for one alarm rule.',clarify:'Use the right symbols and show what happens when the condition is both true and false.',starter:'The flowchart starts… It reads… The decision asks… On Yes… On No…',example:'Start leads to Read button. A diamond asks “Is the button pressed?”. Yes leads to buzzer on; No leads to buzzer off. Both paths return to read the button again.'})
    ]
  },
  {
    id: 4, title: 'Read changing data', subtitle: 'Measure analogue inputs and turn ranges into useful behaviour.', activity: 'POT investigation laboratory',
    sections: [
      section('4.1 Analogue readings show a range', `<p>An analogue input represents many possible values rather than only two states. On this equipment, <code>analogRead()</code> returns a value across the Arduino input range. The potentiometer on A5 changes as its knob turns.</p><p>Record actual low, middle and high readings from the board instead of assuming every component reaches identical extremes.</p>`, {term:'analogue input',definition:'an input that can represent a range of values',purpose:'measure a changing physical condition with more detail than on or off',action:'read A5 repeatedly and observe values in the Serial Monitor',badAction:'assume the only possible readings are zero and one',benefit:'the program can respond proportionally or at several thresholds',risk:'unmeasured assumptions can create thresholds that never occur in practice',control:'collect minimum, middle and maximum observations from the actual device',evidence:'a labelled table of knob positions and recorded readings',misconception:'analogue always means perfectly continuous and noise-free data',correction:'the microcontroller reports one of many numeric levels and readings can vary slightly',scenario:'The knob is halfway but the displayed value is not exactly half the maximum.',response:'record the real value and use measured data for later mapping'}, {prompt:'Record and interpret a low, middle and high potentiometer reading.',clarify:'Connect each knob position to actual data and explain why calibration matters.',starter:'At the low position… In the middle… At the high position… These readings show…',example:'My readings increased as the knob turned. The middle was close to, but not exactly, half the highest reading, so the program should use measured values rather than assumptions.'}),
      section('4.2 Mapping converts one range to another', `<p><code>map()</code> converts a value from one numeric range into another. A potentiometer reading can be mapped to a useful delay, number of lit LEDs or permitted output range.</p><pre><code>level = map(potReading, lowInput, highInput, 0, 6);</code></pre><p>Mapping changes the scale; it does not physically change the sensor. Inputs outside the chosen calibration range may need to be constrained.</p>`, {term:'mapping',definition:'converting a value from one numeric range to a corresponding value in another range',purpose:'make sensor data suitable for controlling an output parameter',action:'state both input and output ranges and test their endpoints',badAction:'use unexplained range numbers copied from another system',benefit:'one changing input can control timing, levels or frequency meaningfully',risk:'reversed or unsuitable endpoints can produce unexpected behaviour',control:'test known low, middle and high values after mapping',evidence:'a mapping table showing input values and predicted outputs',misconception:'map changes the electrical component itself',correction:'map performs a calculation on the numeric reading',scenario:'A six-LED meter needs levels from 0 to 6.',response:'map the calibrated sensor range to 0–6, then test each boundary'}, {prompt:'Plan a mapping from potentiometer readings to a six-level LED display.',clarify:'State the measured input range, output range and predicted results at three points.',starter:'I will map input values from… to… into output levels… A reading of… should…',example:'I will map my measured A5 range to levels 0–6. The lowest reading should light no LEDs, a middle reading about three, and the highest all six.'}),
      section('4.3 Calibrate before judging behaviour', `<p><strong>Calibration</strong> connects raw readings to the real conditions being measured. Take several readings at useful positions, note variation and choose thresholds or map endpoints supported by evidence.</p><p>Change one variable at a time during testing. If both code and hardware position change together, it becomes difficult to identify the cause of a result.</p>`, {term:'calibration',definition:'using measured reference conditions to interpret and configure sensor readings',purpose:'make program decisions fit the real component and environment',action:'collect repeated readings at named conditions before setting thresholds',badAction:'copy a threshold without testing the actual device',benefit:'the system responds where the designer intends it to',risk:'lighting, component variation or noise can shift readings',control:'use a small data set, choose a justified boundary and retest',evidence:'a calibration table and a threshold justified from observed values',misconception:'one sensor reading is enough to define reliable behaviour',correction:'several observations reveal range and variation',scenario:'Readings near the chosen threshold move above and below it rapidly.',response:'collect more data and adjust the rule or tolerance based on evidence'}, {prompt:'Explain how you would calibrate an analogue input before using it in an alarm.',clarify:'Describe the conditions, repeated readings, threshold choice and retest.',starter:'First I would place the sensor… I would record… I would choose… Then…',example:'I would record several readings in the intended normal and alert conditions. I would place the threshold between the clusters, then retest both conditions and values close to the boundary.'})
    ]
  },
  {
    id: 5, title: 'Sense the light', subtitle: 'Use the LDR to detect environmental change and trigger outputs.', activity: 'LDR night-light investigation',
    sections: [
      section('5.1 The LDR turns light into data', `<p>The light-dependent resistor on A4 contributes to a circuit whose analogue reading changes with light conditions. The exact direction and size of the change should be observed on the supplied board.</p><p>The sensor provides data; it does not decide what counts as dark. The program’s threshold and branch create that meaning.</p>`, {term:'light-dependent input',definition:'a sensor input whose reported value changes with the amount of light reaching it',purpose:'allow a control system to respond to changing light conditions',action:'read A4 under named lighting conditions and record the actual direction of change',badAction:'state that a higher number always means darker without checking the board',benefit:'the system can detect changes that a simple button cannot',risk:'shadows and room lighting can make readings inconsistent',control:'control the test position and measure several times',evidence:'a table connecting observed conditions to A4 readings',misconception:'the LDR decides whether the alarm should sound',correction:'the LDR supplies data and the program applies the decision rule',scenario:'Covering the sensor changes the number in Serial Monitor.',response:'record the new value and direction of change before designing the condition'}, {prompt:'Describe an investigation that reveals how A4 responds to light.',clarify:'Name controlled conditions, repeated readings and what conclusion the data supports.',starter:'I will test the LDR in… For each condition… The data will show…',example:'I will keep the board still and record several A4 readings in bright, normal and covered conditions. Comparing the ranges will show whether the reading rises or falls as light decreases.'}),
      section('5.2 Thresholds create categories', `<p>A <strong>threshold</strong> is a chosen boundary used to separate readings into categories. A night light might treat one side as “dark” and the other as “bright”.</p><p>A useful threshold sits between measured condition ranges and is tested near the boundary. The comparison operator—such as <code>&lt;</code> or <code>&gt;</code>—must match the observed direction of the sensor data.</p>`, {term:'threshold',definition:'a chosen boundary used to separate data into categories or trigger a response',purpose:'turn a range of sensor readings into a clear program decision',action:'choose the boundary from calibration evidence and use the matching comparison',badAction:'select a round number because it looks convenient',benefit:'the system can distinguish normal and alert conditions',risk:'a boundary inside noisy readings can cause rapid switching',control:'test values on both sides and adjust using recorded evidence',evidence:'a number-line or table showing ranges, threshold and resulting branch',misconception:'a threshold is the same as the sensor reading',correction:'the reading changes while the threshold is a chosen comparison value',scenario:'The dark readings are lower than the bright readings.',response:'use a less-than comparison if values below the boundary should trigger the dark response'}, {prompt:'Choose and justify an LDR threshold from a small set of readings.',clarify:'Show the two condition ranges, place the boundary and state which comparison will trigger the output.',starter:'The normal readings were… The alert readings were… I chose… because… The condition is…',example:'Bright readings were 700–760 and covered readings 210–280. I chose 500 because it separates the groups. A reading below 500 will trigger the dark branch.'}),
      section('5.3 A night light is a feedback rule', `<p>A basic night-light program repeatedly reads the LDR, compares the value with a threshold, and updates an LED. Repetition matters because the environment can change after the first reading.</p><p>Testing should include both expected conditions, a value near the threshold and recovery when light returns. A system that turns on but never returns to normal is incomplete.</p>`, {term:'sensor-response loop',definition:'a repeating cycle that reads a sensor, applies a rule and updates an output',purpose:'keep the system responsive as conditions change',action:'read, compare, act and repeat while defining both branches',badAction:'read the sensor only once in setup',benefit:'the output can update when the environment changes',risk:'an undefined normal branch can leave an old alert output active',control:'set every relevant output in both the true and false paths',evidence:'a test log showing trigger, recovery and near-threshold behaviour',misconception:'once an alarm output turns on it will automatically reset',correction:'the code must explicitly define the recovery state',scenario:'The LED turns on in darkness but stays on when light returns.',response:'check the else branch and ensure it writes the LED off state'}, {prompt:'Trace a complete night-light loop through dark and bright conditions.',clarify:'Explain the read, comparison, output and recovery path in order.',starter:'The loop reads… When the value… the program… When light returns…',example:'The loop reads A4 and compares it with the calibrated threshold. A dark-range reading turns the LED on. When the reading returns to the bright range, the else branch turns it off before the loop repeats.'})
    ]
  },
  {
    id: 6, title: 'Make the code choose', subtitle: 'Read the button, branch with if/else and remember state.', activity: 'Button and toggle laboratory',
    sections: [
      section('6.1 Read a digital input', `<p><code>digitalRead(7)</code> reads the ThinkerShield push button. The supplied button arrangement may report <code>LOW</code> when pressed and <code>HIGH</code> when released, so observe the real values before writing the condition.</p><p>Name the stored value clearly, such as <code>buttonState</code>. A meaningful name makes later comparisons easier to trace.</p>`, {term:'digital input',definition:'an input read as one of two logic states such as HIGH or LOW',purpose:'let a program detect a two-state event such as a button press',action:'read pin 7 and verify which value represents pressed on the actual board',badAction:'assume pressed must always equal HIGH',benefit:'the program can respond to a deliberate user action',risk:'reversing the logic makes the response occur at the wrong time',control:'print or test both physical states before writing the branch',evidence:'a two-row table matching button position, read value and meaning',misconception:'HIGH always means the button is physically pressed',correction:'the electrical arrangement determines which logic state is reported',scenario:'The LED turns on when the button is released instead of pressed.',response:'check the observed button values and correct the condition'}, {prompt:'Explain how you would determine the pressed and released values on pin 7.',clarify:'Describe an observation-based test rather than guessing the button logic.',starter:'I would read pin 7 while… Then… If the values show…',example:'I would print the pin 7 value while the button is released, then press it and record the new value. Those observations define which state the condition should test.'}),
      section('6.2 If/else creates two paths', `<p>An <code>if</code> statement runs a block when its condition is true. An optional <code>else</code> block runs when the condition is false. Equality uses <code>==</code>; assignment uses <code>=</code>.</p><pre><code>if (buttonState == LOW) { tone(3, 800); }
else { noTone(3); }</code></pre><p>Both branches should establish a complete, safe output state.</p>`, {term:'if/else branch',definition:'a conditional structure that selects one action path when a condition is true and another when it is false',purpose:'give the system different responses for different input states',action:'write a testable condition and define outputs in both branches',badAction:'use assignment where an equality comparison is intended',benefit:'the system can behave differently in normal and alert states',risk:'outputs omitted from one branch can remain in an earlier state',control:'trace once with the condition true and once false',evidence:'a truth table matching input state, condition result and output action',misconception:'if and else run one after the other every time',correction:'only the branch selected by the condition runs on that pass',scenario:'The condition is false for the current button reading.',response:'follow the else block and apply the outputs defined there'}, {prompt:'Trace an if/else alarm rule for both possible button states.',clarify:'Show the condition result and every output action on both paths.',starter:'When the button value is… the condition is… so… Otherwise…',example:'When buttonState is LOW, the comparison is true and the buzzer sounds. When it is HIGH, the condition is false, so the else branch stops the buzzer.'}),
      section('6.3 A variable can remember state', `<p>A toggle changes an output once per button press: off to on, then on to off. A Boolean variable can remember the current state using <code>true</code> or <code>false</code>.</p><p>One physical press can produce several rapid readings, called switch bounce. The supplied activity may use a simple release check or timing strategy; implement only the teacher-directed method and explain its purpose.</p>`, {term:'stored state',definition:'a value retained by the program so later behaviour can depend on what happened earlier',purpose:'allow one button to toggle between two output states',action:'change the Boolean once for a recognised press and write the output from that state',badAction:'set the state true on every loop while the button remains held',benefit:'the system can remember whether an output is currently on or off',risk:'multiple rapid reads can create several unintended toggles',control:'use the teacher-directed press recognition or debounce approach',evidence:'a state table showing previous state, event and new state',misconception:'the button itself remembers the LED state',correction:'the program stores the state in a variable',scenario:'One press appears to switch the LED several times.',response:'check how the program recognises a single press and applies the approved bounce control'}, {prompt:'Explain the state changes in a one-button LED toggle.',clarify:'Trace at least two presses and show what is remembered between them.',starter:'The stored state begins… On the first recognised press… Between presses… On the second…',example:'The Boolean begins false, so the LED is off. The first recognised press changes it to true and turns the LED on. That value remains until the second press changes it back to false.'})
    ]
  },
  {
    id: 7, title: 'Turn numbers into sound', subtitle: 'Control the buzzer with tone, mapping and musical sequences.', activity: 'Buzzer and pitch laboratory',
    sections: [
      section('7.1 Tone controls frequency', `<p>The buzzer on pin 3 can produce a tone using a chosen frequency. Frequency is measured in hertz and relates to perceived pitch: a higher frequency usually sounds higher.</p><p><code>tone(3, frequency)</code> starts the sound; <code>noTone(3)</code> stops it. Classroom volume, duration and testing routines remain Teacher to confirm.</p>`, {term:'tone frequency',definition:'the number of sound-wave cycles per second used to set the buzzer pitch',purpose:'control the pitch used by an audible output',action:'send a suitable frequency to buzzer pin 3 and stop it deliberately',badAction:'leave an unnecessary continuous tone running during all testing',benefit:'sound can communicate alert level or system state',risk:'unexpected or prolonged sound can disrupt safe classroom work',control:'use short teacher-directed tests and explicit noTone commands',evidence:'a table connecting tested frequencies with observed pitch',misconception:'frequency and loudness are the same property',correction:'frequency mainly controls pitch; it does not directly specify perceived loudness',scenario:'The program needs silence in the normal state.',response:'call noTone(3) in the normal branch'}, {prompt:'Explain how the program starts, changes and stops a buzzer tone.',clarify:'Use pin, frequency, pitch and noTone accurately.',starter:'The buzzer is connected to… A frequency of… produces… To stop…',example:'The program calls tone on pin 3 with a chosen frequency. Raising that number raises the pitch. The normal-state branch calls noTone on pin 3 to stop the sound.'}),
      section('7.2 Sensor data can control pitch', `<p>A pitch changer reads the potentiometer, maps its input range to a useful frequency range and sends that result to the buzzer. The signal path is A5 → <code>analogRead</code> → <code>map</code> → <code>tone</code> on pin 3.</p><p>Choose the output range by testing, not by assuming that every numeric frequency is equally useful for the classroom task.</p>`, {term:'data-driven output',definition:'an output parameter calculated from current input data',purpose:'make the response change proportionally as the input changes',action:'map calibrated A5 readings to a tested frequency range',badAction:'send the raw sensor value without considering the useful output range',benefit:'one dial position can produce a corresponding audible state',risk:'an unsuitable range may be inaudible, unpleasant or unhelpful',control:'test low, middle and high mapped frequencies under teacher direction',evidence:'an IPO trace plus input-to-frequency table',misconception:'map creates sound by itself',correction:'map calculates a number and tone uses that number as frequency',scenario:'Turning the dial changes A5 but the buzzer pitch does not change.',response:'trace the stored reading, mapped variable and frequency passed to tone'}, {prompt:'Trace the pitch changer from the potentiometer to the buzzer.',clarify:'Explain every data transformation in order and why mapping is needed.',starter:'A5 supplies… analogRead… map converts… tone then…',example:'A5 supplies a changing reading. analogRead stores it, map converts the calibrated input range to tested frequencies, and tone uses the mapped number to set the buzzer pitch on pin 3.'}),
      section('7.3 Sequences can create a melody', `<p>A melody is an ordered sequence of note frequencies and durations. Arrays can store related notes; a loop can visit each position; a function can keep repeated playing steps together.</p><p>Trace completed source code before changing it. The learning purpose is to identify iteration, arrays and a function—not to copy an unexplained song.</p>`, {term:'programmed sequence',definition:'an ordered collection of values and actions processed to create a planned result',purpose:'produce a repeatable pattern such as notes with matching durations',action:'keep related arrays aligned and iterate through valid positions',badAction:'change one array length without checking the other',benefit:'complex repeated behaviour can be organised with less duplicated code',risk:'an invalid index can retrieve the wrong value or move outside the intended data',control:'check array length and loop boundaries before upload',evidence:'an annotated trace of two sequence positions and their outputs',misconception:'an array plays music automatically',correction:'the loop and function read array values and send commands to the buzzer',scenario:'The notes array has eight items but the loop attempts nine positions.',response:'correct the loop boundary so it visits only valid indexes'}, {prompt:'Explain how an array, loop and function cooperate to play a short tune.',clarify:'Assign a distinct job to each programming structure and trace one note.',starter:'The array stores… The loop… The function… For one index…',example:'The arrays store note frequencies and durations. The loop visits each valid index, and the playing function sends that note to the buzzer for the matching time.'})
    ]
  },
  {
    id: 8, title: 'Combine parts into systems', subtitle: 'Use arrays, functions and iteration in multi-output challenges.', activity: 'Combined-system challenge lab',
    sections: [
      section('8.1 Arrays organise related values', `<p>An array stores several values under one name, with each position identified by an index. The first item uses index 0. An LED pin array can hold the six fixed output pins 8–13.</p><p>Arrays are useful when the same operation must be applied to a set of related components.</p>`, {term:'array',definition:'an ordered collection of related values accessed by index',purpose:'store and process groups such as several LED pin numbers efficiently',action:'define the six pins and access only valid indexes from 0 to 5',badAction:'treat the sixth item as index 6 in a six-item array',benefit:'the same code pattern can work across many components',risk:'an off-by-one error can access outside the intended array',control:'compare loop boundaries with the number of stored items',evidence:'an index table matching array positions to ThinkerShield LED pins',misconception:'the first array item has index 1',correction:'in Arduino C++, the first array position is index 0',scenario:'A loop visits indexes 0, 1, 2, 3, 4, 5 for six LEDs.',response:'recognise that the boundary covers all six valid positions exactly once'}, {prompt:'Create and explain an indexed array for the six ThinkerShield LEDs.',clarify:'Show each index and pin, then explain why the final valid index is 5.',starter:'The array stores… Index 0 refers to… The last valid index is… because…',example:'The array stores pins 8, 9, 10, 11, 12 and 13. Index 0 refers to pin 8 and index 5 to pin 13. Six items occupy positions 0–5.'}),
      section('8.2 Loops and functions reduce repetition', `<p>A <code>for</code> loop repeats a block while updating a counter. A function groups a named task that can be called when needed. Together they can switch several LEDs without duplicating six nearly identical commands.</p><p>Reducing repetition is useful only when the result remains readable and the loop boundaries are correct.</p>`, {term:'iteration',definition:'repeating a set of instructions according to a controlled rule',purpose:'apply the same operation efficiently across values or components',action:'use a loop counter as the valid array index',badAction:'repeat with no end condition or valid boundary',benefit:'shorter code is easier to update consistently',risk:'a wrong comparison can skip an item or run once too many',control:'trace the first, middle and final iteration by hand',evidence:'a trace table showing counter, selected pin and action',misconception:'a loop always makes code easier regardless of its design',correction:'the loop must be bounded, readable and suited to repeated work',scenario:'The counter starts at 0 and continues while it is less than 6.',response:'predict six iterations using indexes 0 through 5'}, {prompt:'Trace a for loop that visits all six LED pins in an array.',clarify:'Show counter values, selected pins and the stopping condition.',starter:'The counter begins… On each iteration… When it reaches…',example:'The counter begins at 0, selects array item 0 and continues through item 5. When it becomes 6, the less-than-6 condition is false and the loop stops.'}),
      section('8.3 Combined challenges expose interactions', `<p>Electronic Dice, Buzzing Light Meter and LED Magic Sign combine earlier ideas. A useful system description separates its input, processing rules and outputs before examining individual code lines.</p><p>When a combined build fails, divide it into subsystems. Test the input reading, the calculation or branch, then each output. Changing many parts at once hides evidence.</p>`, {term:'system decomposition',definition:'breaking a complex system into smaller subsystems that can be understood and tested',purpose:'manage interactions in multi-input or multi-output code',action:'test input, processing and output stages separately before recombining them',badAction:'rewrite the whole sketch after one unexplained symptom',benefit:'faults can be localised with less guesswork',risk:'interactions can make a working component appear faulty',control:'use a known input and test one subsystem at a time',evidence:'an IPO diagram plus subsystem test results for one challenge',misconception:'a combined system should be debugged as one indivisible block',correction:'subsystems can be isolated and verified before integration',scenario:'The light meter reads sensible A4 data but no LEDs illuminate.',response:'keep the input evidence and test mapping, level calculation and LED outputs in order'}, {prompt:'Decompose one combined challenge into subsystems and propose a test order.',clarify:'Choose Dice, Light Meter or Magic Sign, then separate input, processing and outputs.',starter:'The input subsystem… The processing subsystem… The output subsystem… I would test… first because…',example:'For the Buzzing Light Meter, A4 is the input, mapping and level selection are processing, and LEDs plus buzzer are outputs. I would verify A4 first, then calculated level, then each output.'})
    ]
  },
  {
    id: 9, title: 'Design the final alarm', subtitle: 'Turn the supplied brief into a planned, coded and tested alert system.', activity: 'Final alarm design studio',
    sections: [
      section('9.1 Translate the brief into criteria', `<p>The final challenge is to design, produce and evaluate a ThinkerShield alarm or alert system that protects something you care about. It must use the fixed available inputs and outputs, with outputs changing according to input data.</p><p>Write testable criteria for function, clarity, reliability and explanation. Current marks, due date, rubric and submission route remain <strong>Teacher to confirm</strong>.</p>`, {term:'design criterion',definition:'a testable statement used to judge whether a solution succeeds',purpose:'turn the design brief into checkpoints for development and evaluation',action:'write observable criteria linked to the user, purpose and required system behaviour',badAction:'use vague claims such as “the alarm is good”',benefit:'testing and evaluation can use agreed evidence rather than opinion',risk:'unmeasurable criteria make success impossible to judge fairly',control:'include a condition, expected response and quality where relevant',evidence:'a criteria table with planned test method for each item',misconception:'criteria and constraints mean the same thing',correction:'criteria judge success while constraints limit the design space',scenario:'A criterion says only “It works.”',response:'rewrite it to state the triggering input and observable LED or buzzer response'}, {prompt:'Write a concise design brief and at least five testable success criteria for your alarm.',clarify:'Name what is protected, the user need, required system behaviour and how success will be checked.',starter:'I will design… for… It will be successful when…',example:'I will design a desk-item alert that uses light and button data. One criterion is that covering the LDR triggers a red light and audible tone within one loop cycle, then returns to normal when light returns.'}),
      section('9.2 Plan the complete signal path', `<p>Before coding, decide the job of each input and output. Build an IPO diagram, pseudocode and flowchart that agree with one another and the fixed pin map.</p><p>Plan normal, warning and alert states where useful. Each state should explicitly set all relevant LEDs and the buzzer so old outputs do not remain active accidentally.</p>`, {term:'system plan',definition:'a coordinated representation of components, data flow, decisions and intended behaviour',purpose:'make the whole solution traceable before implementation',action:'align the pin map, IPO diagram, pseudocode and flowchart',badAction:'create planning artefacts that describe different rules',benefit:'coding becomes translation rather than invention at the keyboard',risk:'inconsistent plans create faults that are hard to explain',control:'cross-check one scenario through every representation',evidence:'matching pin map, IPO diagram, pseudocode and decision flowchart',misconception:'planning ends once code is typed',correction:'the plan remains a reference for testing and justified revision',scenario:'The flowchart uses the LDR but the pseudocode reads only the button.',response:'resolve the inconsistency before implementing the sketch'}, {prompt:'Plan the final alarm using a pin map, IPO description and complete pseudocode.',clarify:'Make the three representations describe the same inputs, rules and outputs.',starter:'PIN MAP… INPUTS… PROCESSING RULES… OUTPUTS… PSEUDOCODE…',example:'A4 supplies light data and pin 7 supplies the button. The program compares light with a calibrated threshold and checks the button, then selects normal or alert LED and buzzer outputs.'}),
      section('9.3 Test against predictions', `<p>A useful test log states the input condition, expected output, actual output and next action. Include normal, warning, alert and recovery conditions plus values near any threshold.</p><p>Change one factor at a time and keep evidence. A failed test is useful when it reveals a specific difference between prediction and result.</p>`, {term:'test case',definition:'a defined input condition with an expected result used to check system behaviour',purpose:'provide repeatable evidence that the solution meets its criteria',action:'record input, prediction, actual result and justified change',badAction:'write “tested” without conditions or observations',benefit:'faults and improvements are connected to evidence',risk:'testing only the ideal case can hide boundary and recovery problems',control:'include normal, trigger, boundary and recovery cases',evidence:'a test table with expected versus actual outputs and retest result',misconception:'a failed test means the project has failed',correction:'a failed test can identify what must be corrected and retested',scenario:'The alarm triggers correctly but never returns to normal.',response:'record the failure, inspect the recovery branch, change one cause and retest'}, {prompt:'Create a five-case alarm test plan including boundary and recovery evidence.',clarify:'For each case, name the input condition, expected output and evidence you will record.',starter:'Test 1 condition… Expected… Evidence… If actual differs…',example:'For recovery, I will move the LDR from alert light levels back to the calibrated normal range. I expect the buzzer to stop and green LED to turn on; I will record the actual state and code change if needed.'})
    ]
  },
  {
    id: 10, title: 'Debug, improve and explain', subtitle: 'Use evidence to correct faults and evaluate the finished system.', activity: 'Testing and evaluation builder',
    sections: [
      section('10.1 Debug one cause at a time', `<p>Debugging is a systematic process: reproduce the fault, compare the observed and expected result, isolate the likely stage, change one cause and retest.</p><p>Compiler messages often point near a syntax problem, not always exactly at it. Check the reported line, the line before it, matching braces, semicolons, names and pin references.</p>`, {term:'systematic debugging',definition:'a repeatable evidence-based process for finding and correcting faults',purpose:'replace random changes with focused investigation',action:'reproduce, isolate, change one cause and retest',badAction:'change several unrelated lines at once',benefit:'the cause of improvement remains understandable',risk:'random edits can add new faults or hide the original one',control:'keep a short record of symptom, hypothesis, change and result',evidence:'a debugging log linking each change to a retest',misconception:'the line named by a compiler is always the exact source of the error',correction:'syntax problems earlier in the sketch can be reported on a later line',scenario:'The compiler flags a line that appears correct.',response:'inspect the previous line and matching braces before making broad changes'}, {prompt:'Document one fault using symptom, likely cause, single change and retest result.',clarify:'Show your reasoning and evidence, not just the final corrected code.',starter:'The expected result was… Instead… My likely cause was… I changed… The retest…',example:'I expected the red LED on pin 13, but pin 12 lit. I found 12 in digitalWrite, changed only that pin to 13 and retested; the intended LED then responded.'}),
      section('10.2 Evaluation uses criteria and evidence', `<p>Evaluation is a judgement of how well the solution met the brief and criteria. Use observations, test results, code traces and user feedback where authorised.</p><p>For each important criterion, state the evidence, make a judgement and identify a specific improvement. “It worked” is incomplete because it does not show which conditions were tested.</p>`, {term:'evidence-based evaluation',definition:'a reasoned judgement of success supported by relevant test evidence',purpose:'decide how well the solution met its brief and criteria',action:'connect each judgement to a named criterion and observed result',badAction:'describe the building process without judging the outcome',benefit:'strengths and weaknesses can be defended and improved',risk:'unsupported praise can hide unreliable behaviour',control:'use criterion, evidence, judgement and improvement as a repeated pattern',evidence:'a criterion-by-criterion evaluation citing test records',misconception:'evaluation means saying whether you enjoyed the task',correction:'personal reflection can contribute, but solution quality must be judged against evidence',scenario:'A student writes “The alarm was good because it worked.”',response:'name a criterion, cite a test result and explain the level of success'}, {prompt:'Evaluate the final alarm against at least five criteria using test evidence.',clarify:'For every criterion, give a result, judgement and precise improvement where needed.',starter:'For the criterion… the test showed… Therefore… A specific improvement is…',example:'For reliable recovery, four of five tests returned to normal correctly. The criterion was partly met. I would add a better boundary rule and repeat near-threshold tests.'}),
      section('10.3 Responsible digital practice protects work', `<p>Save named versions of code as directed and keep a backup before major changes. This website stores practice responses only in the current browser; it does not upload to Drive or submit to Classroom.</p><p>Explain borrowed ideas and keep your final code understandable. Current file naming, Drive location, Classroom turn-in and collaboration rules remain <strong>Teacher to confirm</strong>.</p>`, {term:'responsible digital practice',definition:'safe, organised and honest handling of digital work, data and authorship',purpose:'protect evidence and make the development process trustworthy',action:'keep teacher-directed backups, meaningful names and clear acknowledgement of sources',badAction:'overwrite the only working copy before an untested change',benefit:'work can be recovered, compared and explained',risk:'device-local data or a single file can be lost when devices or storage change',control:'download a folio backup and follow the confirmed class storage process',evidence:'named versions, a backup record and source acknowledgement where required',misconception:'autosave on this page submits work to the teacher',correction:'browser storage is device-local practice and formal submission is separate',scenario:'A student is changing device after completing written responses.',response:'download the folio backup and follow the teacher-confirmed transfer and submission method'}, {prompt:'Create a final backup and hand-in readiness checklist without assuming the submission route.',clarify:'Separate device-local website evidence, code files, acknowledgement and Teacher to confirm arrangements.',starter:'Before changing device… For my code… I have acknowledged… My teacher must confirm…',example:'I will download the folio backup, save a named copy of the tested sketch and record any source code used. The current Drive folder, file naming and Classroom submission steps remain Teacher to confirm.'})
    ]
  }
];
